<template><PageFrame><PageIntro eyebrow="Work / 02" title="Selected projects" accent="." intro="Scientific software, embedded systems, data analysis, and web products." /><section class="page-section work-section"><div class="shell project-list"><article v-for="project in projects" :key="project.title" class="project" :class="project.accent"><div class="project-index">{{ project.index }}</div><div class="project-main"><div class="project-kicker"><p class="project-type">{{ t(project.type) }}</p><time>{{ project.period }}</time></div><h3>{{ t(project.title) }}</h3><p>{{ t(project.description) }}</p><ul class="tags"><li v-for="tag in project.tags" :key="tag">{{ tag }}</li></ul><a v-if="isCampaignArchive(project.href)" class="project-link" href="/campaign/">{{ t(project.cta) }} <ArrowUpRight :size="15" /></a><router-link v-else-if="project.href?.startsWith('/')" class="project-link" :to="project.href">{{ t(project.cta) }} <ArrowUpRight :size="15" /></router-link><a v-else-if="project.href" class="project-link" :href="project.href" target="_blank" rel="noopener noreferrer">{{ t(project.cta) }} <ArrowUpRight :size="15" /></a><a v-if="project.github" class="project-link secondary-link" :href="project.github" target="_blank" rel="noopener noreferrer">{{ t('Source on GitHub') }} <Github :size="15" /></a></div><div class="project-glyph" aria-hidden="true"><span></span><i></i></div></article></div></section></PageFrame></template>
<script setup>import { ArrowUpRight, Github } from 'lucide-vue-next'; import PageFrame from '../components/PageFrame.vue'; import PageIntro from '../components/PageIntro.vue'; import { useProjectStore } from '../composables/useProjectStore'; import { useLocale } from '../composables/useLocale'; const { visibleProjects: projects } = useProjectStore(); const { t } = useLocale(); const isCampaignArchive = (href) => href === '/campaign' || href === '/campaign/'</script>
